precision mediump float;
uniform sampler2D uMainSampler; uniform float uTime; uniform float uAmp;
varying vec2 outTexCoord;
void main() {
  vec2 uv = outTexCoord;
  float borde = 0.35 + 0.65 * clamp(abs(uv.x - 0.5) * 2.2, 0.0, 1.0);
  float w = sin(uTime * 1.1 + uv.y * 5.0) * 0.65 + sin(uTime * 1.9 + uv.y * 13.0 + uv.x * 3.0) * 0.35;
  uv.x += w * uAmp * borde;
  uv.y += sin(uTime * 0.9 + uv.x * 6.0) * uAmp * 0.35 * borde;
  gl_FragColor = texture2D(uMainSampler, uv);
}
